+        ('Provider finish_reason: error', 'error'),
+        ('Provider finish_reason: error', 'error'),
+        ('Provider finish_reason: network_error', 'network_error'),
+      ];
+      var calls = 0;
+      final wrapped = transientRetryStreamFunction((
+        model,
+        context, {
